295: // Handle touch start
296: let touchStartX = 0;
297: let touchStartY = 0;
298: 
299: function handleTouchStart(e) {
300:   if (gameState.isMatchmaking) return;
301:   touchStartX = e.changedTouches[0].clientX;
302:   touchStartY = e.changedTouches[0].clientY;
303: }
304: 
305: function handleTouchMove(e) {
306:   e.preventDefault();
307: }
308: 
309: function handleTouchEnd(e) {
310:   if (gameState.isMatchmaking) return;
311:   const touchEndX = e.changedTouches[0].clientX;
312:   const touchEndY = e.changedTouches[0].clientY;
313:   
314:   const diffX = touchEndX - touchStartX;
315:   const diffY = touchEndY - touchStartY;
316:   
317:   // Determine swipe direction
318:   if (Math.abs(diffY) > Math.abs(diffX)) {
319:     // Vertical swipe
320:     if (diffY > 30) {
321:       performSwing();
322:     } else if (diffY < -30) {
323:       // Down swipe - maybe drop ball/stop
324:     }
325:   } else {
326:     // Horizontal swipe
327:     if (Math.abs(diffX) > 30) {
328:       if (diffX > 30) dodgeRight();
329:       else dodgeLeft();
330:     }
331:   }
332: }
