462:   // Boundary checks
463:   if (ball.y > 380 || ball.y < 20) {
464:     ball.vy = -ball.vy * 0.8;
465:   }
466:   
467:   // Update DOM
468:   const ballEl = document.getElementById('tennis-ball');
469:   ballEl.style.left = `${ball.x - ball.radius}px`;
470:   ballEl.style.top = `${ball.y - ball.radius}px`;
471:   
472:   // Swing logic
473:   if (gameState.tennis.swingActive) {
474:     // Apply swing force
475:     ball.vx += gameState.tennis.swingDirection * 15;
476:     ball.vy -= 10;
477:     gameState.tennis.swingActive = false;
