73:   font-weight: bold;
74:   border: none;
75:   border-radius: 4px;
76:   cursor: pointer;
77:   transition: all 0.2s;
78:   background: var(--bg-medium);
79:   color: var(--fg-light);
80: }
81: 
82: .menu-options .btn-sport:hover,
83: .menu-options .btn-option:hover {
84:   background: var(--wii-blue);
85:   transform: translateY(-2px);
86: }
87: 
88: .menu-options .btn-sport:active,
89: .menu-options .btn-option:active {
90:   transform: translateY(0);
91: }
92: 
93: /* Character Creator */
94: .creator-panel {
95:   display: flex;
96:   align-items: center;
97:   justify-content: space-between;
98:   max-width: 800px;
99:   margin: 0 auto;
100:   padding: 20px;
101: }
102: 
103: .creator-character {
104:   width: 150px;
105:   height: 200px;
106:   background: var(--bg-medium);
107:   border-radius: 8px;
108:   position: relative;
109:   border: 2px solid var(--wii-blue);
110: }
111: 
112: .creator-character::after {
113:   content: '';
114:   position: absolute;
115:   width: 30px;
116:   height: 20px;
117:   background: var(--wii-yellow);
118:   bottom: -10px;
119:   left: 50%;
120:   margin-left: -15px;
121:   border-radius: 50%;
122: }
123: 
124: .creator-controls {
125:   display: flex;
126:   flex-direction: column;
127:   gap: 10px;
128:   max-width: 200px;
129: }
130: 
131: .btn-control {
132:   padding: 8px 12px;
133:   background: var(--bg-medium);
134:   border: 1px solid var(--fg-muted);
135:   border-radius: 4px;
136:   cursor: pointer;
137:   font-size: 12px;
138:   color: var(--fg-light);
139: }
140: 
141: .btn-control:hover {
142:   border-color: var(--wii-blue);
143:   background: var(--wii-blue-dark);
144: }
145: 
146: .color-picker {
147:   display: flex;
148:   align-items: center;
149:   gap: 10px;
150:   margin-top: 10px;
151: }
152: 
153: .color-picker span {
154:   color: var(--fg-muted);
155:   font-size: 12px;
156: }
157: 
158: .color-picker input {
159:   width: 50px;
160:   height: 25px;
161:   cursor: pointer;
162: }
163: 
164: /* Sport Screens */
165: .sport-header {
166:   display: flex;
167:   justify-content: space-between;
168:   align-items: center;
169:   padding: 20px;
170:   border-bottom: 2px solid var(--fg-muted);
171:   margin-bottom: 20px;
172: }
173: 
174: .sport-header h2 {
175:   font-size: 24px;
176:   color: var(--wii-blue);
177: }
178: 
179: .timer {
180:   background: var(--wii-blue);
181:   color: white;
182:   padding: 5px 10px;
183:   border-radius: 4px;
184:   font-size: 12px;
185:   font-weight: bold;
186: }
187: 
188: .hidden {
189:   display: none;
190: }
191: 
192: .game-area {
193:   position: relative;
194:   height: 400px;
195:   background: var(--bg-medium);
196:   border: 2px solid var(--wii-blue);
197:   overflow: relative;
198: }
199: 
200: /* Game specific styles will be added dynamically */
201: 
202: /* Controls */
203: .controls-instruction {
204:   padding: 15px 20px;
205:   background: var(--bg-medium);
206:   border-top: 2px solid var(--fg-muted);
207:   font-size: 12px;
208:   color: var(--fg-muted);
209: }
210: 
211: .controls-instruction p {
212:   margin-bottom: 5px;
213: }
214: 
215: /* Result Screen */
216: #result-screen {
217:   text-align: center;
218:   padding: 60px 20px;
219: }
220: 
221: #result-screen h2 {
222:   font-size: 40px;
223:   margin-bottom: 10px;
224: }
225: 
226: #result-screen p {
227:   font-size: 16px;
228:   color: var(--fg-muted);
229:   margin-bottom: 30px;
230: }
231: 
232: /* Buttons */
233: .btn-back,
234: .btn-sport, .btn-option {
235:   display: inline-block;
236:   margin: 10px;
237:   padding: 10px 20px;
238:   font-size: 14px;
239:   font-weight: bold;
240:   border: none;
241:   border-radius: 4px;
242:   cursor: pointer;
243:   transition: all 0.2s;
244:   background: var(--bg-medium);
245:   color: var(--fg-light);
246: }
247: 
248: .btn-back:hover,
249: .btn-sport:hover,
250: .btn-option:hover {
251:   background: var(--wii-blue);
252: }
253: 
254: .btn-back:active,
255: .btn-sport:active,
256: .btn-option:active {
257:   transform: translateY(0);
258: }
259: 
260: /* Responsive */
261: @media (max-width: 600px) {
262:   .menu-options .btn-sport,
263:   .menu-options .btn-option {
264:     width: 100%;
265:     margin: 5px 0;
266:   }
267:   
268:   .creator-controls {
269:     align-items: center;
270:   }
271: }
272: 
273: /* HUD Buttons */
274: .hud {
275:   position: absolute;
276:   bottom: 0;
277:   width: 100%;
278:   padding: 15px;
279:   background: rgba(26, 26, 26, 0.8);
280:   backdrop-filter: blur(10px);
281:   border-top: 2px solid var(--wii-blue);
282:   display: flex;
283:   gap: 10px;
284:   justify-content: center;
285:   flex-wrap: wrap;
286:   z-index: 100;
287: }
288: 
289: .hud-btn {
290:   display: inline-block;
291:   padding: 10px 20px;
292:   font-size: 13px;
293:   font-weight: bold;
294:   border: none;
295:   border-radius: 6px;
296:   cursor: pointer;
297:   transition: all 0.15s;
298:   background: var(--bg-medium);
299:   color: var(--fg-light);
300:   min-width: 120px;
301:   text-align: center;
302:   white-space: nowrap;
303:   border: 1px solid var(--fg-muted);
304: }
305: 
306: .hud-btn:hover {
307:   background: var(--wii-blue);
308:   border-color: var(--wii-blue);
309:   transform: translateY(-2px);
310:   box-shadow: 0 4px 12px rgba(58, 151, 217, 0.4);
311: }
312: 
313: .hud-btn:active {
314:   transform: translateY(0);
315:   background: var(--wii-blue-dark);
316: }
317: 
318: .hud-btn.hud-activated {
319:   background: var(--wii-yellow);
320:   color: var(--bg-dark);
321:   transform: scale(0.98);
322:   box-shadow: inset 0 2px 4px rgba(0,0,0,0.2);
323: }
324: 
325: .hud-btn:focus-visible {
326:   outline: 2px solid var(--wii-yellow);
327:   outline-offset: 2px;
328: }
329: 
330: /* Sport-specific HUD groupings */
331: .hud-pitching,
332: .hud-batting,
333: .hud-clubs,
334: .hud-spin,
335: .hud-power {
336:   display: flex;
337:   flex-direction: column;
338:   gap: 8px;
339:   align-items: center;
340: }
341: 
342: .hud-pitching > .hud-btn,
343: .hud-batting > .hud-btn,
344: .hud-clubs > .hud-btn,
345: .hud-spin > .hud-btn,
346: .hud-power > .hud-btn {
347:   min-width: 110px;
348: }
349: 
350: /* Tennis HUD */
351: .tennis-btn {
352:   background: var(--wii-green);
353:   color: white;
354:   border-color: var(--wii-green);
355: }
356: 
357: .tennis-btn:hover {
358:   background: #54c466;
359:   box-shadow: 0 4px 12px rgba(115, 173, 33, 0.4);
360: }
361: 
362: /* Baseball HUD */
363: .baseball-btn {
364:   background: var(--wii-red);
365:   color: white;
366:   border-color: var(--wii-red);
367: }
368: 
369: .baseball-btn:hover {
370:   background: #e84118;
371:   box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
372: }
373: 
374: /* Golf HUD */
375: .golf-btn {
376:   background: var(--wii-orange);
377:   color: white;
378:   border-color: var(--wii-orange);
379: }
380: 
381: .golf-btn:hover {
382:   background: #ff7c40;
383:   box-shadow: 0 4px 12px rgba(255, 107, 53, 0.4);
384: }
385: 
386: /* Bowling HUD */
387: .bowling-btn {
388:   background: var(--wii-blue);
389:   color: white;
390:   border-color: var(--wii-blue);
391: }
392: 
393: .bowling-btn:hover {
394:   background: #5a9fd8;
395:   box-shadow: 0 4px 12px rgba(58, 151, 217, 0.4);
396: }
397: 
398: /* Boxing HUD */
399: .box-btn {
400:   background: var(--wii-red);
401:   color: white;
402:   border-color: var(--wii-red);
403: }
404: 
405: .box-btn:hover {
406:   background: #e84118;
407:   box-shadow: 0 4px 12px rgba(228, 26, 28, 0.4);
408: }

input.content:
@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Outfit:wght@400;500;600;700;800;900&display=swap');
:root{--ink:#193449;--muted:#75899a;--blue:#278aca;--blue-dark:#176b9f;--sky:#dff3fa;--paper:#f7fafb;--line:#e4ebef;--coral:#f25c54;--yellow:#f4bd3c;--green:#45a675;--navy:#16374d;--shadow:0 12px 38px #204a6012}*{box-sizing:border-box}html,body{margin:0;min-height:100%;font-family:'DM Sans',sans-serif;color:var(--ink)}body{background:#edf4f6;min-height:100vh}button,input{font:inherit}button{color:inherit}#app{min-height:100vh;overflow:hidden}.screen{display:none;min-height:100vh}.screen.active{display:flex}.eyebrow{font:500 10px 'DM Mono',monospace;letter-spacing:.2em;color:#aac0ca}.eyebrow.blue{color:#4d8faf}.screen em{font-family:Georgia,serif;font-weight:400;color:#3c9acf}
/* title */.title-screen{position:relative;align-items:center;justify-content:center;text-align:center;background:linear-gradient(180deg,#8dd5ed 0%,#d1f1f5 48%,#84cbd2 49%,#53aeb5 100%);overflow:hidden}.title-island{position:absolute;inset:0;overflow:hidden}.sun{position:absolute;width:94px;height:94px;top:11%;right:19%;border-radius:50%;background:#ffe5a0;box-shadow:0 0 70px #fff4bb99}.cloud{position:absolute;width:130px;height:32px;background:#fff;border-radius:40px;opacity:.8}.cloud:before,.cloud:after{content:'';position:absolute;bottom:8px;border-radius:50%;background:inherit}.cloud:before{width:53px;height:53px;left:21px}.cloud:after{width:42px;height:42px;left:66px}.cloud-one{top:22%;left:13%;transform:scale(.85)}.cloud-two{top:30%;right:11%;transform:scale(1.1)}.distant-island{position:absolute;left:0;right:0;bottom:43%;height:115px;background:#81b765;clip-path:polygon(0 75%,8% 60%,15% 65%,23% 22%,32% 61%,44% 34%,51% 58%,65% 17%,74% 58%,81% 36%,90% 66%,100% 43%,100% 100%,0 100%)}.water{position:absolute;bottom:0;left:0;right:0;height:47%;background:repeating-linear-gradient(175deg,transparent 0 28px,#ffffff26 29px 31px,transparent 32px 57px),linear-gradient(180deg,#78ced1,#47a8b4)}.water:before{content:'';position:absolute;inset:-35px -10% auto;height:65px;background:#82bc69;clip-path:polygon(0 70%,11% 42%,21% 60%,30% 19%,41% 55%,51% 36%,62% 72%,74% 21%,84% 53%,100% 33%,100% 100%,0 100%)}.title-palms{position:absolute;left:0;right:0;bottom:33%;height:160px}.title-palms i{position:absolute;bottom:0;width:10px;height:110px;background:#785b3e;border-radius:8px;transform:rotate(12deg)}.title-palms i:before{content:'✦';position:absolute;top:-40px;left:-32px;font-size:69px;color:#417c53;text-shadow:19px 8px #50885b,-13px 10px #59945f}.title-palms i:nth-child(1){left:10%;transform:scale(.85) rotate(-12deg)}.title-palms i:nth-child(2){left:30%;transform:scale(.65) rotate(9deg)}.title-palms i:nth-child(3){right:28%;transform:scale(.7) rotate(-8deg)}.title-palms i:nth-child(4){right:11%;transform:scale(1.05) rotate(12deg)}.title-palms i:nth-child(5){right:44%;transform:scale(.48) rotate(-6deg)}.title-lockup{z-index:1;position:absolute;top:13%;left:0;right:0;color:#fff;text-shadow:0 5px 16px #2569824a}.title-lockup .eyebrow{color:#f7ffff}.title-lockup h1{font:900 clamp(54px,9vw,100px)/.79 'Outfit',sans-serif;letter-spacing:-.08em;margin:19px 0 15px}.title-lockup h1 em{font:400 .72em Georgia,serif;color:#fff;letter-spacing:-.04em}.title-lockup p{font:500 10px 'DM Mono',monospace;letter-spacing:.28em;color:#eefaff}.press-start{z-index:2;position:absolute;bottom:15%;border:1px solid #ffffffac;background:#fffffff0;border-radius:50px;padding:12px 25px 12px 13px;display:grid;grid-template-columns:44px auto;grid-template-rows:24px 16px;column-gap:13px;align-items:center;cursor:pointer;box-shadow:0 8px 26px #17546b35;transition:.2s}.press-start:hover{transform:translateY(-3px);box-shadow:0 14px 32px #17546b42}.start-orb{grid-row:span 2;width:40px;height:40px;background:var(--coral);color:white;display:grid;place-items:center;border-radius:50%;font-size:13px}.press-start>span:nth-child(2){font:700 12px 'DM Mono',monospace;letter-spacing:.08em;text-align:left}.press-start small{font:9px 'DM Mono',monospace;color:#8598a2;text-align:left}.title-footer{position:absolute;z-index:1;bottom:26px;left:30px;right:30px;display:flex;justify-content:space-between;font:9px 'DM Mono',monospace;letter-spacing:.15em;color:#e3f7f6}
/* lobby */.lobby-screen{display:block;background:var(--paper);min-height:100vh}.topbar{height:74px;padding:0 clamp(22px,6vw,88px);display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #e8eef0;background:#ffffffb8}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:var(--ink);font:800 13px/1 'Outfit',sans-serif;letter-spacing:.03em}.brand b{color:#3c9acf}.brand small{display:block;font:8px 'DM Mono',monospace;letter-spacing:.24em;color:#91a5b0;margin-top:5px}.brand-mark{width:32px;height:32px;background:var(--coral);color:white;border-radius:10px;display:grid;place-items:center;font:700 20px Georgia}.topbar-right{display:flex;align-items:center;gap:9px;color:#76909f;font:9px 'DM Mono',monospace;letter-spacing:.1em}.online-dot{width:7px;height:7px;background:#57bb83;border-radius:50%;box-shadow:0 0 0 4px #57bb831e}.player-chip{margin-left:17px;border-left:1px solid var(--line);padding-left:17px;display:flex;align-items:center;gap:8px;color:var(--ink)}.player-chip>span{font-size:20px}.lobby-content{max-width:1080px;padding:48px 30px 24px;margin:auto}.lobby-intro{display:flex;align-items:center;justify-content:space-between;margin-bottom:28px}.lobby-intro h2{font:600 clamp(34px,4.2vw,51px)/1.03 'Outfit',sans-serif;letter-spacing:-.055em;margin:9px 0 11px}.lobby-intro p{font-size:13px;color:#8094a0;margin:0}.island-stamp{width:88px;height:88px;border:1px solid #d6e8ed;border-radius:50%;display:flex;flex-direction:column;justify-content:center;align-items:center;transform:rotate(8deg);color:#4c99b7}.island-stamp>span{font-size:19px}.island-stamp b{font:700 9px/1.1 'DM Mono',monospace;text-align:center;letter-spacing:.08em}.island-stamp small{font:7px 'DM Mono',monospace;letter-spacing:.2em;margin-top:4px;color:#9ab0b9}.sport-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:12px}.sport-card{height:152px;grid-column:span 2;border:1px solid transparent;border-radius:5px;position:relative;text-align:left;padding:14px 16px;cursor:pointer;overflow:hidden;transition:.2s;box-shadow:0 4px 14px #25495b08}.sport-card:nth-child(4){grid-column:2/span 2}.sport-card:nth-child(5){grid-column:4/span 2}.sport-card:hover{transform:translateY(-4px);box-shadow:0 12px 23px #25495b18}.card-tennis{background:#e8f4dc;border-color:#daebca}.card-baseball{background:#fae9e2;border-color:#f5dbd2}.card-golf{background:#e1f1e7;border-color:#d1e9db}.card-boxing{background:#f1e8f4;border-color:#e6d9eb}.card-bowling{background:#e3eef6;border-color:#d2e3ee}.card-index{position:absolute;top:14px;left:16px;font:9px 'DM Mono',monospace;letter-spacing:.1em;color:#76909a}.sport-illustration{position:absolute;right:26px;top:32px;font-size:55px;filter:drop-shadow(0 6px 6px #27435c1c);transition:.25s}.sport-card:hover .sport-illustration{transform:rotate(-9deg) scale(1.12)}.card-copy{position:absolute;bottom:14px;left:16px;display:flex;flex-direction:column;gap:4px}.card-copy b{font:700 15px 'Outfit',sans-serif;letter-spacing:.05em}.card-copy small{color:#728896;font-size:10px}.card-arrow{position:absolute;bottom:15px;right:16px;color:#72909d;font-size:19px}.lobby-bottom{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;margin-top:20px}.utility-card{min-height:65px;background:#fff;border:1px solid var(--line);border-radius:4px;padding:12px;display:flex;align-items:center;gap:11px;text-align:left;cursor:pointer;transition:.2s}.utility-card:hover{border-color:#9fcbdc;transform:translateY(-2px)}.utility-icon{width:35px;height:35px;background:#eff8fb;color:#3e9bc0;display:grid;place-items:center;border-radius:50%;font-size:19px}.utility-card>span:nth-child(2){display:flex;flex-direction:column;gap:4px}.utility-card b{font:700 10px 'DM Mono',monospace;letter-spacing:.04em}.utility-card small{font-size:9px;color:#8396a0}.utility-arrow{margin-left:auto;color:#3d9ac0;font-size:18px}.online-card .utility-icon{background:#fff3e0;color:#e3a32f}.lobby-weather{display:flex;align-items:center;justify-content:center;gap:9px;color:#dba739}.lobby-weather>span{font-size:24px}.lobby-weather span+span{display:flex;flex-direction:column;gap:4px}.lobby-weather b{font:700 9px 'DM Mono',monospace;color:#6b8491;letter-spacing:.07em}.lobby-weather small{font-size:10px;color:#98a8af}.lobby-footer{max-width:1080px;margin:10px auto 0;border-top:1px solid var(--line);padding:15px 30px;display:flex;justify-content:space-between;font:8px 'DM Mono',monospace;letter-spacing:.12em;color:#9aacb4}.lobby-footer b{color:#4c9abe}
/* creator */.sub-screen{display:block;background:var(--paper);padding:28px max(24px,calc((100vw - 1000px)/2)) 45px}.sub-header{display:flex;align-items:center;gap:22px;border-bottom:1px solid var(--line);padding-bottom:22px}.back-button{border:0;background:transparent;color:#72909e;font:500 10px 'DM Mono',monospace;letter-spacing:.08em;cursor:pointer}.back-button:hover{color:var(--blue)}.sub-header h2{font:600 31px 'Outfit',sans-serif;margin:4px 0 0;letter-spacing:-.04em}.step-pill{margin-left:auto;border:1px solid var(--line);padding:8px 11px;font:9px 'DM Mono',monospace;color:#8da0aa;letter-spacing:.1em}.creator-layout{display:grid;grid-template-columns:1fr 1fr;gap:65px;max-width:940px;margin:36px auto}.avatar-stage{position:relative;min-height:460px;background:#e4f3f5;overflow:hidden;display:flex;flex-direction:column;justify-content:flex-end;align-items:center}.avatar-stage:before{content:'';position:absolute;bottom:0;width:150%;height:150px;background:#a5d6b3;clip-path:ellipse(50% 45% at 50% 100%)}.stage-sun{position:absolute;top:48px;right:60px;width:62px;height:62px;border-radius:50%;background:#ffdf91;box-shadow:0 0 0 14px #ffdf912c}.avatar-scene{z-index:1;position:relative;height:330px;width:100%;display:flex;justify-content:center;align-items:flex-end}.avatar-shadow{position:absolute;width:145px;height:28px;bottom:7px;border-radius:50%;background:#557d7350;filter:blur(4px)}.avatar{position:absolute;width:186px;height:306px;bottom:13px;animation:bob 3s ease-in-out infinite}.avatar-head{position:absolute;width:154px;height:154px;left:16px;top:10px;background:#f3c59a;border:3px solid #e1a97b;border-radius:49% 49% 45% 45%;z-index:2;box-shadow:inset 0 -7px #dca87f35}.avatar-hair{position:absolute;z-index:3;top:3px;left:20px;width:146px;height:48px;background:#59392f;border-radius:80% 75% 15% 15%;clip-path:polygon(4% 55%,10% 12%,24% 26%,35% 0,48% 24%,64% 5%,72% 25%,94% 8%,100% 72%,77% 55%,61% 64%,43% 52%,26% 64%)}.avatar-eyes{position:absolute;top:66px;left:39p