4: // Game state
5: const gameState = {
6:   currentSport: null,
7:   currentMode: 'single', // 'single' or 'online'
8:   player1: { mii: null, ready: false },
9:   player2: { mii: null, ready: false },
10:   score: { p1: 0, p2: 0 },
11:   matchmakingTime: 0,
12:   matchmakingInterval: null,
13:   isMatchmaking: false
14: };
15: 
16: // Sports data
17: const sports = {
18:   tennis: {
19:     name: 'Tennis',
20:     description: 'Doubles matches focusing on swing timing, angle, and spin',
21:     controls: 'Swipe up/forward to swing, swipe angle determines power and curve',
22:     init: initTennis,
23:     update: updateTennis,
24:     render: renderTennis
25:   },
26:   baseball: {
27:     name: 'Baseball',
28:     description: '3-inning games - bat and pitch with timing',
29:     controls: 'Swipe up to swing/batter, swipe to pitch with curve',
30:     init: initBaseball,
31:     update: updateBaseball,
32:     render: renderBaseball
33:   },
34:   golf: {
35:     name: 'Golf',
36:     description: '3-hole or 9-hole courses accounting for wind, elevation, slope',
37:     controls: 'Select club, aim, swipe up to hit with loft and backspin',
38:     init: initGolf,
39:     update: updateGolf,
40:     render: renderGolf
41:   },
42:   boxing: {
43:     name: 'Boxing',
44:     description: '3-round matches - guard, dodge, throw jabs, hooks, uppercuts',
45:     controls: 'Swipe up/forward to punch, swipe side-to-side to dodge',
46:     init: initBoxing,
47:     update: updateBoxing,
48:     render: renderBoxing
49:   },
50:   bowling: {
51:     name: 'Bowling',
52:     description: 'Standard 10-frame bowling - adjust position, angle, wrist twist',
53:     controls: 'Swipe up to roll ball, curve swipe to add spin',
54:     init: initBowling,
55:     update: updateBowling,
56:     render: renderBowling
57:   }
58: };
59: 
60: // Character creator state
61: const creatorState = {
62:   gender: 'male',
63:   headShape: 'default',
64:   hairStyle: 'default',
65:   eyebrowStyle: 'default',
66:   eyeStyle: 'default',
67:   noseStyle: 'default',
68:   mouthStyle: 'default',
69:   facialHair: 'none',
70:   glasses: 'none',
71:   outfitColor: '#FFC425' // Wii Yellow
72: };
73: 
74: // Mii character Proportions (nostalgic)
75: const miiProportions = {
76:   hand: { type: 'sphere', size: 0.8, float: true },
77:   torso: { type: 'capsule', height: 1.2, width: 0.8 },
78:   leg: { type: 'stub', length: 0.4 },
79:   foot: { type: 'small', size: 0.3 }
80: };
81: 
82: // Initialize the game
83: document.addEventListener('DOMContentLoaded', () => {
84:   initCharacterCreator();
85:   initEventListeners();
86:   startMenuMusic();
87: });
88: 
89: // Go back to main menu
90: function goBack() {
91:   showScreen('main-menu');
92:   resetGame();
93: }
94: 
95: // Show a screen, hide others
96: function showScreen(screenId) {
97:   document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
98:   document.getElementById(screenId).classList.add('active');
99: }
100: 
101: // Initialize character creator
102: function initCharacterCreator() {
103:   const miiDiv = document.getElementById('miicharacter');
104:   updateMiiDisplay();
105:   
106:   // Color picker
107:   document.getElementById('outfit-color').addEventListener('input', (e) => {
108:     creatorState.outfitColor = e.target.value;
109:     updateMiiDisplay();
110:   });
111: }
112: 
113: // Update the Miidisplay based on creator state
114: function updateMiiDisplay() {
115:   const miiDiv = document.getElementById('miicharacter');
116:   miiDiv.innerHTML = '';
117:   
118:   const mii = document.createElement('div');
119:   mii.className = 'mi-character';
120:   
121:   // Head
122:   mii.style.width = '100px';
123:   mii.style.height = '120px';
124:   mii.style.background = '#FFC425';
125:   mii.style.borderRadius = '50% 50% 50% 50% / 60% 60% 40% 40%';
126:   mii.style.position = 'relative';
127:   mii.style.margin = '10px auto';
128:   
129:   // Eyes
130:   const eyeColor = '#000';
131:   const eyeSize = 8;
132:   const eyes = [
133:     { x: 25, y: 35, size: eyeSize },
134:     { x: 75, y: 35, size: eyeSize }
135:   ];
136:   
137:   eyes.forEach((eye, i) => {
138:     const eyeEl = document.createElement('div');
139:     eyeEl.style.position = 'absolute';
140:     eyeEl.style.width = `${eye.size}px`;
141:     eyeEl.style.height = `${eye.size}px`;
142:     eyeEl.style.background = eyeColor;
143:     eyeEl.style.borderRadius = '50%';
144:     eyeEl.style.left = `${eye.x}px`;
145:     eyeEl.style.top = `${eye.y}px`;
146:     mii.appendChild(eyeEl);
147:   });
148:   
149:   // Mouth
150:   const mouthY = 70;
151:   const mouthEl = document.createElement('div');
152:   mouthEl.style.position = 'absolute';
153:   mouthEl.style.width = '40px';
154:   mouthEl.style.height = '6px';
155:   mouthEl.style.background = '#000';
156:   mouthEl.style.borderRadius = '2px';
157:   mouthEl.style.left = '30px';
158:   mouthEl.style.top = `${mouthY}px`;
159:   mii.appendChild(mouthEl);
160:   
161:   // Hair (simple)
162:   const hairStyles = {
163:     'default': { color: '#000', height: 15 },
164:     'spiky': { color: '#000', height: 20 },
165:     'short': { color: '#000', height: 10 }
166:   };
167:   
168:   const hair = hairStyles[creatorState.hairStyle] || hairStyles['default'];
169:   const hairEl = document.createElement('div');
170:   hairEl.style.position = 'absolute';
171:   hairEl.style.width = '100%';
172:   hairEl.style.height: `${hair.height}px`;
173:   hairEl.style.background = hair.color;
174:   hairEl.style.borderRadius: '0 0 50% 50% / 0 0 60% 60%';
175:   hairEl.style.marginTop: '-10px';
176:   mii.appendChild(hairEl);
177:   
178:   // Body details based on features
179:   // Eyebrows
180:   const browY = 25;
181:   const browEl = document.createElement('div');
182:   browEl.style.position = 'absolute';
183:   browEl.style.width = '40px';
184:   browEl.style.height = '6px';
185:   browEl.style.background = '#000';
186:   browEl.style.borderRadius = '2px';
187:   browEl.style.left = '20px';
188:   browEl.style.top = `${browY}px`;
189:   mii.appendChild(browEl);
190:   
191:   const browEl2 = document.createElement('div');
192:   browEl2.style.position = 'absolute';
193:   browEl2.style.width = '40px';
194:   browEl2.style.height = '6px';
195:   browEl2.style.background = '#000';
196:   browEl2.style.borderRadius = '2px';
197:   browEl2.style.left = '60px';
198:   browEl2.style.top = `${browY}px';
199:   mii.appendChild(browEl2);
200:   
201:   // Outfit color
202:   mii.style.background = creatorState.outfitColor;
203:   
204:   miiDiv.appendChild(mii);
205: }
