207: // Initialize event listeners
208: function initEventListeners() {
209:   // Sport selection
210:   document.querySelectorAll('.btn-sport').forEach(btn => {
211:     btn.addEventListener('click', () => {
212:       const sport = btn.dataset.sport;
213:       startSport(sport);
214:     });
215:   });
216:   
217:   // Customize option
218:   document.querySelectorAll('.btn-option').forEach(btn => {
219:     btn.addEventListener('click', () => {
220:       const option = btn.dataset.option;
221:       if (option === 'customize') {
222:         showScreen('creator');
223:       } else if (option === 'online') {
224:         startMatchmaking();
225:       }
226:     });
227:   });
228:   
229:   // Character creator controls
230:   document.querySelectorAll('.btn-control').forEach(btn => {
231:     btn.addEventListener('click', () => {
232:       const feat = btn.dataset.feat;
233:       // Cycle through options for each feature
234:       switch(feat) {
235:         case 'gender':
236:           creatorState.gender = creatorState.gender === 'male' ? 'female' : 'male';
237:           break;
238:         case 'head-shape':
239:           creatorState.headShape = getNextHeadShape(creatorState.headShape);
240:           break;
241:         case 'hair':
242:           const hairs = ['default', 'spiky', 'short'];
